  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM
// B is MxN
// C is MxN
//note that due to Fortran array layout, the code below more closely resembles upper triangular case in BLAS
#pragma scop
{
  int i0, k0, jt, jj, kk;
  enum { JB = 32, KB = 32 };
  DATA_TYPE temp2_tile[JB];

  #pragma omp parallel for private(i0, k0, jj, kk, temp2_tile) schedule(static)
  for (jt = 0; jt < _PB_N; jt += JB) {
    int jend = jt + JB;
    if (jend > _PB_N) jend = _PB_N;

    for (i0 = 0; i0 < _PB_M; i0++) {
      for (jj = jt; jj < jend; jj++)
        temp2_tile[jj - jt] = 0.0;

      for (k0 = 0; k0 < i0; k0 += KB) {
        int kend = k0 + KB;
        if (kend > i0) kend = i0;

        for (kk = k0; kk < kend; kk++) {
          DATA_TYPE aik = A[i0][kk];
          DATA_TYPE alpha_aik = alpha * aik;

          #pragma omp simd
          for (jj = jt; jj < jend; jj++) {
            C[kk][jj] += alpha_aik * B[i0][jj];
            temp2_tile[jj - jt] += B[kk][jj] * aik;
          }
        }
      }

      {
        DATA_TYPE aii = A[i0][i0];

        #pragma omp simd
        for (jj = jt; jj < jend; jj++)
          C[i0][jj] = beta * C[i0][jj]
                      + alpha * B[i0][jj] * aii
                      + alpha * temp2_tile[jj - jt];
      }
    }
  }
}
#pragma endscop

}


